-- ============================================================
--  Experiencias de clase: Curso de Respuesta a Requerimientos del INVIMA
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  33 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Respuesta a Requerimientos del INVIMA$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Respuesta a Requerimientos del INVIMA$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite$t$
     AND m.title = $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite$t$, $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite","texto":"En un titular de registros sanitarios que opera en Colombia, el INVIMA requiere información adicional y el plazo empieza a correr. Lo que está en juego es el criterio de introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite con tus propias palabras y reconocer por qué importa en curso de Respuesta a Requerimientos del INVIMA.","Relacionar introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite con unidad 1. El auto de requerimiento en el procedimiento administrativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Comprende el lugar del auto de requerimiento en el trámite de registro sanitario y el recorrido del curso desde la notificación hasta los recursos."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite aparece en medio de una decisión que no admite improvisación: el INVIMA requiere información adicional y el plazo empieza a correr. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. El auto de requerimiento en el procedimiento administrativo. El objetivo del curso es claro: Que el químico farmacéutico analice un auto de requerimiento del INVIMA, gestione sus plazos y construya una respuesta técnica completa, trazable y oportuna, y que sepa actuar ante el desistimiento, el abandono o la negación del trámite. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Comprende el lugar del auto de requerimiento en el trámite de registro sanitario y el recorrido del curso desde la notificación hasta los recursos.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. El auto de requerimiento en el procedimiento administrativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de vencimientos y solicitud de prórroga.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Identifica la norma aplicable y el plazo de respuesta de cada auto. Evidencia que debe quedar: Registro del paso.","Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda). Evidencia que debe quedar: Registro del paso.","Indica la consecuencia de no responder en cada caso. Evidencia que debe quedar: Registro del paso.","Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse. Evidencia que debe quedar: Registro del paso.","Redacta la solicitud de prórroga motivada. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite»?","respuesta":"Comprende el lugar del auto de requerimiento en el trámite de registro sanitario y el recorrido del curso desde la notificación hasta los recursos."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de vencimientos y solicitud de prórroga.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. El auto de requerimiento en el procedimiento administrativo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Capacitación - Trámite de Registro Sanitario de Medicamentos en Invima a un clic","url":"https://www.youtube.com/watch?v=kMhjktRya9w"},{"cita":"ABC Registros Sanitarios (#13) – trámite, auto de requerimiento, abandono y desistimiento. Invest in Bogotá (ES)","url":"https://es.investinbogota.org/wp-content/uploads/2025/12/ABC-13_RegistrosSanitarios-1.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite"}],"keywords":["curso","respuesta","requerimientos","invima","introducción","requerimiento","define","resultado","trámite","unidad","procedimiento","administrativo"],"mapa":{"centro":"Introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. El auto de requerimiento en el procedimiento administrativo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Cálculo del vencimiento y solicitud de prórroga","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Identifica la norma aplicable y el plazo de respuesta de cada auto.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica la consecuencia de no responder en cada caso.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Redacta la solicitud de prórroga motivada.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Cálculo del vencimiento y solicitud de prórroga","contexto":"Farmacéutica Los Andes (ficticia) recibe tres autos del Invima en la misma semana (datos simulados): (1) un requerimiento en la evaluación farmacéutica de un registro nuevo (Decreto 677 de 1995); (2) un requerimiento en el registro de un medicamento importado; (3) un requerimiento en una modificación por cambio de fabricante del principio activo (Decreto 334 de 2022). El fabricante extranjero avisa que la información del tercer auto tardará siete semanas.","pregunta":"¿Qué decisión demuestra que entendiste introducción al curso: qué es un auto de requerimiento y por qué define el resultado del trámite?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. La solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$La solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015$t$
     AND m.title = $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$La solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015$t$, $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de la solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar la solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015 con tus propias palabras y reconocer por qué importa en curso de Respuesta a Requerimientos del INVIMA.","Relacionar la solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015 con unidad 1. El auto de requerimiento en el procedimiento administrativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar la solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015 y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Reconoce que los trámites sanitarios son peticiones regidas por la norma especial y, de forma supletoria, por el CPACA y la Ley 1755."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, la solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015 aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. El auto de requerimiento en el procedimiento administrativo. El objetivo del curso es claro: Que el químico farmacéutico analice un auto de requerimiento del INVIMA, gestione sus plazos y construya una respuesta técnica completa, trazable y oportuna, y que sepa actuar ante el desistimiento, el abandono o la negación del trámite. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Reconoce que los trámites sanitarios son peticiones regidas por la norma especial y, de forma supletoria, por el CPACA y la Ley 1755.","Una pregunta que se usa para comprobar esta clase es: «Según el artículo 17 de la Ley 1437 de 2011 (sustituido por la Ley 1755 de 2015), ¿qué pasa si el peticionario no completa una petición incompleta en el plazo?» La respuesta correcta se apoya en lo siguiente: El artículo 17 prevé que la autoridad requiera al peticionario para completar la petición en un máximo de un mes, prorrogable por un término igual si se pide antes de vencer. Si no cumple, se entiende que desistió; la autoridad lo declara y archiva con un acto motivado que se notifica personalmente y contra el que solo procede reposición. La petición puede presentarse de nuevo completa. La fuente citada es: Ley 1755 de 2015, art. 17.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. El auto de requerimiento en el procedimiento administrativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de vencimientos y solicitud de prórroga.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar la solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Identifica la norma aplicable y el plazo de respuesta de cada auto. Evidencia que debe quedar: Registro del paso.","Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda). Evidencia que debe quedar: Registro del paso.","Indica la consecuencia de no responder en cada caso. Evidencia que debe quedar: Registro del paso.","Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse. Evidencia que debe quedar: Registro del paso.","Redacta la solicitud de prórroga motivada. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar la solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015 en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «La solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015»?","respuesta":"Reconoce que los trámites sanitarios son peticiones regidas por la norma especial y, de forma supletoria, por el CPACA y la Ley 1755."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de vencimientos y solicitud de prórroga.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["La solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015 se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. El auto de requerimiento en el procedimiento administrativo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Ley 1755 de 2015 – Derecho fundamental de petición (texto: arts. 17 y 18). Unidad para las Víctimas (texto oficial de la ley) (ES)","url":"https://www.unidadvictimas.gov.co/wp-content/uploads/Documentos/ley/Ley_1755_2015.pdf"},{"cita":"[Página web] Ley 1755 de 2015 – Gestor Normativo. Función Pública (ES)","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=65334"},{"cita":"[Página web] Concepto INVIMA 1260 de 2020 – Desistimiento de solicitudes de registro sanitario. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/concepto_invima_0001260_2020.htm"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente la solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015 en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de la solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015"}],"keywords":["curso","respuesta","requerimientos","invima","solicitud","derecho","petición","cpaca","unidad","requerimiento","procedimiento","administrativo"],"mapa":{"centro":"La solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. El auto de requerimiento en el procedimiento administrativo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Cálculo del vencimiento y solicitud de prórroga","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Identifica la norma aplicable y el plazo de respuesta de cada auto.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica la consecuencia de no responder en cada caso.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Redacta la solicitud de prórroga motivada.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"La solicitud ante el INVIMA como derecho de petición: CPACA y Ley 1755 de 2015","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. El auto de requerimiento en el procedimiento administrativo: Farmacéutica Los Andes (ficticia) recibe tres autos del Invima en la misma semana (datos simulados): (1) un requerimiento en la evaluación farmacéutica de un registro nuevo (Decreto 677 de 1995); (2) un requerimiento en el registro de un medicamento importado; (3) un requerimiento en una modificación por cambio de fabricante del principio activo (Decreto 334 de 2022). El fabricante extranjero avisa que la información del tercer auto tardará siete semanas. La pregunta que decide esta clase es: Según el artículo 17 de la Ley 1437 de 2011 (sustituido por la Ley 1755 de 2015), ¿qué pasa si el peticionario no completa una petición incompleta en el plazo?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"La autoridad debe decidir de fondo con la información que tenga en el expediente en ese momento.","correcta":false,"retro":"La norma prevé el desistimiento tácito."},{"texto":"Se entiende que desistió; la autoridad lo declara y archiva con un acto que admite reposición.","correcta":true,"retro":"Correcto. La solicitud puede volver a presentarse completa."},{"texto":"La petición se aprueba automáticamente por silencio administrativo positivo.","correcta":false,"retro":"No opera el silencio positivo en ese caso."},{"texto":"El peticionario recibe una multa y queda inhabilitado para volver a radicar.","correcta":false,"retro":"No hay multa ni inhabilidad; puede radicar de nuevo."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. Peticiones incompletas, desistimiento tácito y desistimiento expreso
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Peticiones incompletas, desistimiento tácito y desistimiento expreso$t$
     AND m.title = $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Peticiones incompletas, desistimiento tácito y desistimiento expreso$t$, $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Peticiones incompletas, desistimiento tácito y desistimiento expreso","texto":"En un titular de registros sanitarios que opera en Colombia, llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. Lo que está en juego es el criterio de peticiones incompletas, desistimiento tácito y desistimiento expreso. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar peticiones incompletas, desistimiento tácito y desistimiento expreso con tus propias palabras y reconocer por qué importa en curso de Respuesta a Requerimientos del INVIMA.","Relacionar peticiones incompletas, desistimiento tácito y desistimiento expreso con unidad 1. El auto de requerimiento en el procedimiento administrativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar peticiones incompletas, desistimiento tácito y desistimiento expreso y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta los arts. 17 y 18 de la Ley 1755 de 2015 y su aplicación por el INVIMA: plazo de un mes, prórroga, archivo y recurso de reposición."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, peticiones incompletas, desistimiento tácito y desistimiento expreso aparece en medio de una decisión que no admite improvisación: llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. El auto de requerimiento en el procedimiento administrativo. El objetivo del curso es claro: Que el químico farmacéutico analice un auto de requerimiento del INVIMA, gestione sus plazos y construya una respuesta técnica completa, trazable y oportuna, y que sepa actuar ante el desistimiento, el abandono o la negación del trámite. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta los arts. 17 y 18 de la Ley 1755 de 2015 y su aplicación por el INVIMA: plazo de un mes, prórroga, archivo y recurso de reposición.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. El auto de requerimiento en el procedimiento administrativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de vencimientos y solicitud de prórroga.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar peticiones incompletas, desistimiento tácito y desistimiento expreso, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Identifica la norma aplicable y el plazo de respuesta de cada auto. Evidencia que debe quedar: Registro del paso.","Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda). Evidencia que debe quedar: Registro del paso.","Indica la consecuencia de no responder en cada caso. Evidencia que debe quedar: Registro del paso.","Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse. Evidencia que debe quedar: Registro del paso.","Redacta la solicitud de prórroga motivada. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar peticiones incompletas, desistimiento tácito y desistimiento expreso en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Peticiones incompletas, desistimiento tácito y desistimiento expreso»?","respuesta":"Interpreta los arts. 17 y 18 de la Ley 1755 de 2015 y su aplicación por el INVIMA: plazo de un mes, prórroga, archivo y recurso de reposición."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de vencimientos y solicitud de prórroga.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Peticiones incompletas, desistimiento tácito y desistimiento expreso se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. El auto de requerimiento en el procedimiento administrativo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Ley 1755 de 2015 – Derecho fundamental de petición (texto: arts. 17 y 18). Unidad para las Víctimas (texto oficial de la ley) (ES)","url":"https://www.unidadvictimas.gov.co/wp-content/uploads/Documentos/ley/Ley_1755_2015.pdf"},{"cita":"[Página web] Concepto INVIMA 16041670 de 2016 – Requerimientos, plazos, desistimiento y abandono. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/compilacion/docs/concepto_invima_16041670_2016.htm"},{"cita":"[Página web] Concepto INVIMA 1260 de 2020 – Desistimiento de solicitudes de registro sanitario. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/concepto_invima_0001260_2020.htm"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente peticiones incompletas, desistimiento tácito y desistimiento expreso en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de peticiones incompletas, desistimiento tácito y desistimiento expreso"}],"keywords":["curso","respuesta","requerimientos","invima","peticiones","incompletas","desistimiento","tácito","expreso","unidad","requerimiento","procedimiento"],"mapa":{"centro":"Peticiones incompletas, desistimiento tácito y desistimiento expreso","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. El auto de requerimiento en el procedimiento administrativo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Cálculo del vencimiento y solicitud de prórroga","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Identifica la norma aplicable y el plazo de respuesta de cada auto.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica la consecuencia de no responder en cada caso.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Redacta la solicitud de prórroga motivada.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Cálculo del vencimiento y solicitud de prórroga","contexto":"Farmacéutica Los Andes (ficticia) recibe tres autos del Invima en la misma semana (datos simulados): (1) un requerimiento en la evaluación farmacéutica de un registro nuevo (Decreto 677 de 1995); (2) un requerimiento en el registro de un medicamento importado; (3) un requerimiento en una modificación por cambio de fabricante del principio activo (Decreto 334 de 2022). El fabricante extranjero avisa que la información del tercer auto tardará siete semanas.","pregunta":"¿Qué decisión demuestra que entendiste peticiones incompletas, desistimiento tácito y desistimiento expreso?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
