      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 04. Actos de trámite y actos definitivos: auto, resolución y firmeza
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Actos de trámite y actos definitivos: auto, resolución y firmeza$t$
     AND m.title = $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Actos de trámite y actos definitivos: auto, resolución y firmeza$t$, $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Actos de trámite y actos definitivos: auto, resolución y firmeza","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de actos de trámite y actos definitivos: auto, resolución y firmeza. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar actos de trámite y actos definitivos: auto, resolución y firmeza con tus propias palabras y reconocer por qué importa en curso de Respuesta a Requerimientos del INVIMA.","Relacionar actos de trámite y actos definitivos: auto, resolución y firmeza con unidad 1. El auto de requerimiento en el procedimiento administrativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar actos de trámite y actos definitivos: auto, resolución y firmeza y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Distingue el auto de requerimiento (acto de trámite, sin recursos) de las resoluciones que deciden de fondo y pueden recurrirse."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, actos de trámite y actos definitivos: auto, resolución y firmeza aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. El auto de requerimiento en el procedimiento administrativo. El objetivo del curso es claro: Que el químico farmacéutico analice un auto de requerimiento del INVIMA, gestione sus plazos y construya una respuesta técnica completa, trazable y oportuna, y que sepa actuar ante el desistimiento, el abandono o la negación del trámite. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Distingue el auto de requerimiento (acto de trámite, sin recursos) de las resoluciones que deciden de fondo y pueden recurrirse.","Una pregunta que se usa para comprobar esta clase es: «Un titular quiere interponer un recurso de reposición contra un auto que le pide información adicional. ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: El artículo 75 del CPACA dispone que no hay recurso contra los actos de trámite, preparatorios o de ejecución, salvo norma en contrario. El auto de requerimiento es un acto de trámite; los recursos proceden contra la resolución que decide de fondo o que declara el desistimiento. La fuente citada es: Ley 1437 de 2011, arts. 74 y 75.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. El auto de requerimiento en el procedimiento administrativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de vencimientos y solicitud de prórroga.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar actos de trámite y actos definitivos: auto, resolución y firmeza, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Identifica la norma aplicable y el plazo de respuesta de cada auto. Evidencia que debe quedar: Registro del paso.","Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda). Evidencia que debe quedar: Registro del paso.","Indica la consecuencia de no responder en cada caso. Evidencia que debe quedar: Registro del paso.","Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse. Evidencia que debe quedar: Registro del paso.","Redacta la solicitud de prórroga motivada. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar actos de trámite y actos definitivos: auto, resolución y firmeza en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Actos de trámite y actos definitivos: auto, resolución y firmeza»?","respuesta":"Distingue el auto de requerimiento (acto de trámite, sin recursos) de las resoluciones que deciden de fondo y pueden recurrirse."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de vencimientos y solicitud de prórroga.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Actos de trámite y actos definitivos: auto, resolución y firmeza se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. El auto de requerimiento en el procedimiento administrativo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Código de Procedimiento Administrativo y de lo Contencioso Administrativo","url":"https://www.youtube.com/watch?v=ZsOMJUhM_2A"},{"cita":"[Página web] Recursos contra los actos administrativos: reposición, apelación y queja. Gerencie.com (ES)","url":"https://www.gerencie.com/recursos-que-proceden-contra-los-actos-administrativos.html"},{"cita":"CPACA – Ley 1437 de 2011 actualizada (2019). Rama Judicial (ES)","url":"https://lector.ramajudicial.gov.co/SIBD/VIDEOTECA/Publicaciones/00000000/51188/Anexos/CPACA%20Ley%201437%20Actualizada%202019.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente actos de trámite y actos definitivos: auto, resolución y firmeza en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de actos de trámite y actos definitivos: auto, resolución y firmeza"}],"keywords":["curso","respuesta","requerimientos","invima","actos","trámite","definitivos","resolución","firmeza","unidad","requerimiento","procedimiento"],"mapa":{"centro":"Actos de trámite y actos definitivos: auto, resolución y firmeza","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. El auto de requerimiento en el procedimiento administrativo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Cálculo del vencimiento y solicitud de prórroga","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Identifica la norma aplicable y el plazo de respuesta de cada auto.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica la consecuencia de no responder en cada caso.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Redacta la solicitud de prórroga motivada.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Actos de trámite y actos definitivos: auto, resolución y firmeza","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. El auto de requerimiento en el procedimiento administrativo: Farmacéutica Los Andes (ficticia) recibe tres autos del Invima en la misma semana (datos simulados): (1) un requerimiento en la evaluación farmacéutica de un registro nuevo (Decreto 677 de 1995); (2) un requerimiento en el registro de un medicamento importado; (3) un requerimiento en una modificación por cambio de fabricante del principio activo (Decreto 334 de 2022). El fabricante extranjero avisa que la información del tercer auto tardará siete semanas. La pregunta que decide esta clase es: Un titular quiere interponer un recurso de reposición contra un auto que le pide información adicional. ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Procede siempre, porque todo acto que expide el Invima admite el recurso de reposición en su contra.","correcta":false,"retro":"Los actos de trámite no admiten recursos."},{"texto":"Procede solo si el auto fue notificado por medios electrónicos.","correcta":false,"retro":"La forma de notificación no cambia la naturaleza del acto."},{"texto":"Procede solo si lo presenta un abogado dentro de los cinco días siguientes.","correcta":false,"retro":"No es la regla para ese tipo de acto."},{"texto":"No procede, porque el auto es un acto de trámite; lo que corresponde es responder dentro del plazo.","correcta":true,"retro":"Correcto. Los recursos proceden contra actos definitivos."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 05. Plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados$t$
     AND m.title = $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados$t$, $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados con tus propias palabras y reconocer por qué importa en curso de Respuesta a Requerimientos del INVIMA.","Relacionar plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados con unidad 1. El auto de requerimiento en el procedimiento administrativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Identifica los plazos de respuesta del Decreto 677 (30, 60 y 40 días hábiles según el trámite) y la consecuencia de no responder (abandono)."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. El auto de requerimiento en el procedimiento administrativo. El objetivo del curso es claro: Que el químico farmacéutico analice un auto de requerimiento del INVIMA, gestione sus plazos y construya una respuesta técnica completa, trazable y oportuna, y que sepa actuar ante el desistimiento, el abandono o la negación del trámite. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Identifica los plazos de respuesta del Decreto 677 (30, 60 y 40 días hábiles según el trámite) y la consecuencia de no responder (abandono).","Una pregunta que se usa para comprobar esta clase es: «El Invima requiere información en la evaluación farmacéutica de un trámite de registro regido por el Decreto 677 de 1995. ¿Qué plazo tiene el interesado para responder?» La respuesta correcta se apoya en lo siguiente: El Decreto 677 de 1995 (art. 23, num. 3) prevé, en la evaluación farmacéutica, un único requerimiento con 30 días hábiles para responder; vencido el término, se entiende abandonada la solicitud. Para medicamentos en normas farmacológicas y nuevos el plazo es de 60 días hábiles (arts. 25 y 29) y para importados de 40 (art. 31). La fuente citada es: Decreto 677 de 1995, arts. 23, 25, 29 y 31.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. El auto de requerimiento en el procedimiento administrativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de vencimientos y solicitud de prórroga.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Identifica la norma aplicable y el plazo de respuesta de cada auto. Evidencia que debe quedar: Registro del paso.","Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda). Evidencia que debe quedar: Registro del paso.","Indica la consecuencia de no responder en cada caso. Evidencia que debe quedar: Registro del paso.","Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse. Evidencia que debe quedar: Registro del paso.","Redacta la solicitud de prórroga motivada. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En un laboratorio ficticio, la notificación electrónica de un auto llegó al correo de una persona que estaba de vacaciones (datos simulados). Nadie registró la fecha; cuando se dieron cuenta, faltaban tres días para vencer el mes y la información del fabricante extranjero tardaría seis semanas. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados»?","respuesta":"Identifica los plazos de respuesta del Decreto 677 (30, 60 y 40 días hábiles según el trámite) y la consecuencia de no responder (abandono)."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de vencimientos y solicitud de prórroga.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. El auto de requerimiento en el procedimiento administrativo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Decreto 677 de 1995 – Régimen de registros sanitarios (copia publicada por INVIMA). INVIMA (ES)","url":"https://www.invima.gov.co/invima_website/static/attachments/medicamentos_bioequivalencia/decreto_677_1995.pdf"},{"cita":"Decreto 0677 de 1995. Ministerio de Salud y Protección Social (ES)","url":"https://minsalud.gov.co/Normatividad_Nuevo/DECRETO%200677%20DE%201995.pdf"},{"cita":"[Página web] Concepto INVIMA 16041670 de 2016 – Requerimientos, plazos, desistimiento y abandono. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/compilacion/docs/concepto_invima_16041670_2016.htm"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados"}],"keywords":["curso","respuesta","requerimientos","invima","plazos","decreto","evaluación","farmacéutica","normas","farmacológicas","medicamentos","nuevos"],"mapa":{"centro":"Plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. El auto de requerimiento en el procedimiento administrativo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Cálculo del vencimiento y solicitud de prórroga","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Identifica la norma aplicable y el plazo de respuesta de cada auto.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica la consecuencia de no responder en cada caso.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Redacta la solicitud de prórroga motivada.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Plazos del Decreto 677 de 1995: evaluación farmacéutica, normas farmacológicas, medicamentos nuevos e importados","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. El auto de requerimiento en el procedimiento administrativo: Farmacéutica Los Andes (ficticia) recibe tres autos del Invima en la misma semana (datos simulados): (1) un requerimiento en la evaluación farmacéutica de un registro nuevo (Decreto 677 de 1995); (2) un requerimiento en el registro de un medicamento importado; (3) un requerimiento en una modificación por cambio de fabricante del principio activo (Decreto 334 de 2022). El fabricante extranjero avisa que la información del tercer auto tardará siete semanas. La pregunta que decide esta clase es: El Invima requiere información en la evaluación farmacéutica de un trámite de registro regido por el Decreto 677 de 1995. ¿Qué plazo tiene el interesado para responder?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Cinco días hábiles, porque la evaluación farmacéutica es un trámite urgente.","correcta":false,"retro":"El Decreto 677 fija un plazo mayor."},{"texto":"Un año calendario, porque la información técnica toma mucho tiempo en reunirse y verificarse.","correcta":false,"retro":"El plazo es de días hábiles, no de un año."},{"texto":"Treinta días hábiles; vencidos, se entiende abandonada la solicitud de evaluación.","correcta":true,"retro":"Correcto. Es un único requerimiento."},{"texto":"No hay plazo: el interesado responde cuando tenga lista la información.","correcta":false,"retro":"Sí hay un plazo y una consecuencia."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 06. Decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones$t$
     AND m.title = $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones$t$, $u$Unidad 1. El auto de requerimiento en el procedimiento administrativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones","texto":"En un titular de registros sanitarios que opera en Colombia, el INVIMA requiere información adicional y el plazo empieza a correr. Lo que está en juego es el criterio de decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones con tus propias palabras y reconocer por qué importa en curso de Respuesta a Requerimientos del INVIMA.","Relacionar decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones con unidad 1. El auto de requerimiento en el procedimiento administrativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Comprende el régimen vigente de requerimientos en renovaciones y modificaciones y su relación con el Decreto 677."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones aparece en medio de una decisión que no admite improvisación: el INVIMA requiere información adicional y el plazo empieza a correr. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. El auto de requerimiento en el procedimiento administrativo. El objetivo del curso es claro: Que el químico farmacéutico analice un auto de requerimiento del INVIMA, gestione sus plazos y construya una respuesta técnica completa, trazable y oportuna, y que sepa actuar ante el desistimiento, el abandono o la negación del trámite. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Comprende el régimen vigente de requerimientos en renovaciones y modificaciones y su relación con el Decreto 677.","Una pregunta que se usa para comprobar esta clase es: «En una modificación regida por el Decreto 334 de 2022, el área regulatoria pide la prórroga del requerimiento dos días después de vencido el mes. ¿Cuál es la mejor valoración?» La respuesta correcta se apoya en lo siguiente: El Decreto 334 de 2022 (art. 8) prevé un único requerimiento con un mes para responder, prorrogable si se pide antes del vencimiento; si no se responde, se entiende que el interesado desiste. Una prórroga pedida después del vencimiento es extemporánea. La fuente citada es: Decreto 334 de 2022, art. 8; Ley 1755 de 2015, art. 17.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. El auto de requerimiento en el procedimiento administrativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de vencimientos y solicitud de prórroga.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Identifica la norma aplicable y el plazo de respuesta de cada auto. Evidencia que debe quedar: Registro del paso.","Calcula el vencimiento de cada uno a partir de una fecha de notificación que definas (en días hábiles o en meses, según corresponda). Evidencia que debe quedar: Registro del paso.","Indica la consecuencia de no responder en cada caso. Evidencia que debe quedar: Registro del paso.","Decide en cuál auto es necesaria la prórroga y hasta cuándo puede pedirse. Evidencia que debe quedar: Registro del paso.","Redacta la solicitud de prórroga motivada. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones»?","respuesta":"Comprende el régimen vigente de requerimientos en renovaciones y modificaciones y su relación con el Decreto 677."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de vencimientos y solicitud de prórroga.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. El auto de requerimiento en el procedimiento administrativo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Decreto 334 de 2022 – Renovación, modificación y suspensión de registros sanitarios. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/decreto_0334_2022.htm"},{"cita":"[Página web] Decreto 334 de 2022 – Gestor Normativo. Función Pública (ES)","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=219130"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones"}],"keywords":["curso","respuesta","requerimientos","invima","decreto","requerimiento","único","plazo","prórroga","desistimiento","renovaciones","modificaciones"],"mapa":{"centro":"Decreto 334 de 2022: requerimiento único, plazo de un mes, prórroga y desistimiento en renovaciones y modificaciones","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. El auto de requerimiento en el procedimiento administrativo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Cálculo del vencimiento y solicitud de prórroga","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Identifica la norma aplicable y el plazo de respuesta de cada auto.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Calcula el vencimiento de cada uno a partir de una fecha de notificación que 