    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 11. Requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos$t$
     AND m.title = $u$Unidad 2. Tipos de requerimientos y lectura de actas de la Comisión Revisora$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos$t$, $u$Unidad 2. Tipos de requerimientos y lectura de actas de la Comisión Revisora$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos con tus propias palabras y reconocer por qué importa en curso de Respuesta a Requerimientos del INVIMA.","Relacionar requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos con unidad 2. Tipos de requerimientos y lectura de actas de la Comisión Revisora y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta los requerimientos de eficacia, seguridad, inserto e información para prescribir que formula la Sala."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Tipos de requerimientos y lectura de actas de la Comisión Revisora. El objetivo del curso es claro: Que el químico farmacéutico analice un auto de requerimiento del INVIMA, gestione sus plazos y construya una respuesta técnica completa, trazable y oportuna, y que sepa actuar ante el desistimiento, el abandono o la negación del trámite. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta los requerimientos de eficacia, seguridad, inserto e información para prescribir que formula la Sala.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 2. Tipos de requerimientos y lectura de actas de la Comisión Revisora y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Lista de requerimientos verificables con responsables y riesgos.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Identifica el tipo de concepto y su efecto en el trámite. Evidencia que debe quedar: Registro del paso.","Clasifica cada requerimiento como legal, farmacéutico o farmacológico. Evidencia que debe quedar: Registro del paso.","Redacta cada requerimiento como una acción verificable. Evidencia que debe quedar: Registro del paso.","Asigna responsable, evidencia esperada y fecha a cada uno. Evidencia que debe quedar: Registro del paso.","Identifica los riesgos de cada punto (por ejemplo, información que no existe). Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Un titular ficticio recibe un concepto de la Sala que «aplaza» la decisión sobre una nueva indicación y pide «allegar análisis por subgrupos y datos de seguridad a largo plazo» (datos simulados). El gerente pregunta si eso significa que negaron el producto. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos»?","respuesta":"Interpreta los requerimientos de eficacia, seguridad, inserto e información para prescribir que formula la Sala."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Lista de requerimientos verificables con responsables y riesgos.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Tipos de requerimientos y lectura de actas de la Comisión Revisora.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Acta No. 10 de 2015 SEMPB – Sesión ordinaria (ejemplos de conceptos y requerimientos). INVIMA (ES)","url":"https://www.invima.gov.co/invima_website/static/attachments/medicamentos_bioequivalencia/Acta_20No._2010_20de_202015_20SEMPB.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos"}],"keywords":["curso","respuesta","requerimientos","invima","farmacológicos","especializada","medicamentos","productos","biológicos","unidad","tipos","lectura"],"mapa":{"centro":"Requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 2. Tipos de requerimientos y lectura de actas de la Comisión Revisora","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Del concepto de la Sala a la lista de requerimientos","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Identifica el tipo de concepto y su efecto en el trámite.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica cada requerimiento como legal, farmacéutico o farmacológico.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Redacta cada requerimiento como una acción verificable.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Asigna responsable, evidencia esperada y fecha a cada uno.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Identifica los riesgos de cada punto (por ejemplo, información que no existe).","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Del concepto de la Sala a la lista de requerimientos","contexto":"Laboratorios Altamira (ficticia) recibe un concepto de la Sala Especializada sobre su solicitud de una nueva concentración de un antihipertensivo (datos simulados). El concepto dice: «La Sala recomienda requerir al interesado para que: a) allegue la justificación clínica de la nueva concentración; b) ajuste las contraindicaciones del inserto a la información del producto de referencia; c) incluya la advertencia sobre hipotensión en adultos mayores; d) presente el plan de gestión de riesgos actualizado». Además, el auto del Invima incluye un requerimiento legal: el certificado de existencia y representación tiene más de tres meses.","pregunta":"¿Qué decisión demuestra que entendiste requerimientos farmacológicos de la Sala Especializada de Medicamentos y Productos Biológicos?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 12. Estructura de un acta: orden del día, ficha del producto, solicitud y concepto
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Estructura de un acta: orden del día, ficha del producto, solicitud y concepto$t$
     AND m.title = $u$Unidad 2. Tipos de requerimientos y lectura de actas de la Comisión Revisora$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Estructura de un acta: orden del día, ficha del producto, solicitud y concepto$t$, $u$Unidad 2. Tipos de requerimientos y lectura de actas de la Comisión Revisora$u$;
