    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 25. Insertos e información para prescribir: ajustes solicitados por la Sala
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Insertos e información para prescribir: ajustes solicitados por la Sala$t$
     AND m.title = $u$Unidad 4. Requerimientos frecuentes por tema técnico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Insertos e información para prescribir: ajustes solicitados por la Sala$t$, $u$Unidad 4. Requerimientos frecuentes por tema técnico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Insertos e información para prescribir: ajustes solicitados por la Sala","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de insertos e información para prescribir: ajustes solicitados por la Sala. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar insertos e información para prescribir: ajustes solicitados por la Sala con tus propias palabras y reconocer por qué importa en curso de Respuesta a Requerimientos del INVIMA.","Relacionar insertos e información para prescribir: ajustes solicitados por la Sala con unidad 4. Requerimientos frecuentes por tema técnico y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar insertos e información para prescribir: ajustes solicitados por la Sala y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta los requerimientos sobre inserto e información para prescribir y cómo presentar las versiones ajustadas."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, insertos e información para prescribir: ajustes solicitados por la Sala aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Requerimientos frecuentes por tema técnico. El objetivo del curso es claro: Que el químico farmacéutico analice un auto de requerimiento del INVIMA, gestione sus plazos y construya una respuesta técnica completa, trazable y oportuna, y que sepa actuar ante el desistimiento, el abandono o la negación del trámite. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta los requerimientos sobre inserto e información para prescribir y cómo presentar las versiones ajustadas.","Una pregunta que se usa para comprobar esta clase es: «La Sala pide ajustar el inserto con una nueva advertencia. El equipo propone enviar solo una frase en la carta. ¿Cuál es la mejor valoración?» La respuesta correcta se apoya en lo siguiente: Los requerimientos sobre inserto e información para prescribir se responden con las versiones ajustadas, identificando los cambios (control de cambios o tabla comparativa) y asegurando la coherencia entre inserto, información para prescribir y etiquetas. La fuente citada es: Decreto 677 de 1995; actas de la Sala Especializada.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 4. Requerimientos frecuentes por tema técnico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de estrategia con respuestas propuestas.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar insertos e información para prescribir: ajustes solicitados por la Sala, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Analiza qué evidencia exige cada requerimiento y si puede obtenerse en 60 días hábiles. Evidencia que debe quedar: Registro del paso.","Propón cómo acotar la vida útil con los datos disponibles y qué compromisos ofrecer. Evidencia que debe quedar: Registro del paso.","Analiza las opciones frente al comparador (justificación con evidencia o nuevo estudio). Evidencia que debe quedar: Registro del paso.","Redacta las respuestas a los requerimientos 3 y 4. Evidencia que debe quedar: Registro del paso.","Decide la estrategia global (responder completo, acotar o desistir y radicar de nuevo) y justifícala. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar insertos e información para prescribir: ajustes solicitados por la Sala en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Insertos e información para prescribir: ajustes solicitados por la Sala»?","respuesta":"Interpreta los requerimientos sobre inserto e información para prescribir y cómo presentar las versiones ajustadas."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de estrategia con respuestas propuestas.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Insertos e información para prescribir: ajustes solicitados por la Sala se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Requerimientos frecuentes por tema técnico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Acta No. 10 de 2015 SEMPB – Sesión ordinaria (ejemplos de conceptos y requerimientos). INVIMA (ES)","url":"https://www.invima.gov.co/invima_website/static/attachments/medicamentos_bioequivalencia/Acta_20No._2010_20de_202015_20SEMPB.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente insertos e información para prescribir: ajustes solicitados por la Sala en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de insertos e información para prescribir: ajustes solicitados por la Sala"}],"keywords":["curso","respuesta","requerimientos","invima","insertos","información","prescribir","ajustes","solicitados","unidad","frecuentes","técnico"],"mapa":{"centro":"Insertos e información para prescribir: ajustes solicitados por la Sala","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 4. Requerimientos frecuentes por tema técnico","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Estrategia ante un auto combinado de estabilidad y bioequivalencia","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Analiza qué evidencia exige cada requerimiento y si puede obtenerse en 60 días hábiles.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Propón cómo acotar la vida útil con los datos disponibles y qué compromisos ofrecer.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Analiza las opciones frente al comparador (justificación con evidencia o nuevo estudio).","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Redacta las respuestas a los requerimientos 3 y 4.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Decide la estrategia global (responder completo, acotar o desistir y radicar de nuevo) y justifícala.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Insertos e información para prescribir: ajustes solicitados por la Sala","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 4. Requerimientos frecuentes por tema técnico: Genéricos del Valle (ficticia) solicitó el registro de tabletas de liberación inmediata de un principio activo con bioequivalencia exigida (datos simulados). El auto requiere: (1) estabilidad de largo plazo de tres lotes en zona IVb que respalde la vida útil propuesta de 36 meses (hoy hay 12 meses de datos); (2) justificar el producto de referencia usado en el estudio de bioequivalencia, que se compró en otro país; (3) incluir la prueba de sustancias relacionadas en las especificaciones de estabilidad; (4) ajustar el inserto con una advertencia pedida por la Sala. El plazo es de 60 días hábiles. La pregunta que decide esta clase es: La Sala pide ajustar el inserto con una nueva advertencia. El equipo propone enviar solo una frase en la carta. ¿Cuál es la mejor valoración?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es mejor presentar el inserto ajustado, con los cambios señalados.","correcta":true,"retro":"Correcto. Facilita la verificación."},{"texto":"Es suficiente, porque el Invima se encarga de editar el inserto final antes de aprobar el registro.","correcta":false,"retro":"El titular presenta la versión ajustada."},{"texto":"Es suficiente si la advertencia se agrega después en la etiqueta de la caja.","correcta":false,"retro":"El ajuste se pide en el inserto."},{"texto":"Es mejor no responder ese punto, porque las advertencias reducen las ventas.","correcta":false,"retro":"No responder lleva a la negación."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 26. Caso práctico: auto combinado de estabilidad y bioequivalencia en un genérico
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso práctico: auto combinado de estabilidad y bioequivalencia en un genérico$t$
     AND m.title = $u$Unidad 4. Requerimientos frecuentes por tema técnico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso práctico: auto combinado de estabilidad y bioequivalencia en un genérico$t$, $u$Unidad 4. Requerimientos frecuentes por tema técnico$u$;
