    v_n := v_n + 1;
  END IF;

  -- 31. Revocatoria directa y alternativas: nueva solicitud o desistimiento
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Revocatoria directa y alternativas: nueva solicitud o desistimiento$t$
     AND m.title = $u$Unidad 5. Notificación, radicación, negaciones y recursos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Revocatoria directa y alternativas: nueva solicitud o desistimiento$t$, $u$Unidad 5. Notificación, radicación, negaciones y recursos$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Revocatoria directa y alternativas: nueva solicitud o desistimiento","texto":"En un titular de registros sanitarios que opera en Colombia, el INVIMA requiere información adicional y el plazo empieza a correr. Lo que está en juego es el criterio de revocatoria directa y alternativas: nueva solicitud o desistimiento. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar revocatoria directa y alternativas: nueva solicitud o desistimiento con tus propias palabras y reconocer por qué importa en curso de Respuesta a Requerimientos del INVIMA.","Relacionar revocatoria directa y alternativas: nueva solicitud o desistimiento con unidad 5. Notificación, radicación, negaciones y recursos y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar revocatoria directa y alternativas: nueva solicitud o desistimiento y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Compara la revocatoria directa con los recursos y con la presentación de una nueva solicitud."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, revocatoria directa y alternativas: nueva solicitud o desistimiento aparece en medio de una decisión que no admite improvisación: el INVIMA requiere información adicional y el plazo empieza a correr. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 5. Notificación, radicación, negaciones y recursos. El objetivo del curso es claro: Que el químico farmacéutico analice un auto de requerimiento del INVIMA, gestione sus plazos y construya una respuesta técnica completa, trazable y oportuna, y que sepa actuar ante el desistimiento, el abandono o la negación del trámite. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Compara la revocatoria directa con los recursos y con la presentación de una nueva solicitud.","Una pregunta que se usa para comprobar esta clase es: «Un titular dejó vencer el plazo del recurso y pide la revocatoria directa alegando que la negación es contraria a la ley. ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: El artículo 93 del CPACA prevé la revocación de actos manifiestamente opuestos a la Constitución o a la ley, no conformes con el interés público o que causen agravio injustificado. Según el artículo 94, la revocación a solicitud de parte por oposición a la ley no procede si el peticionario interpuso los recursos procedentes. La solicitud se resuelve en dos meses (art. 95). La fuente citada es: Ley 1437 de 2011, arts. 93 a 95.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 5. Notificación, radicación, negaciones y recursos y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar revocatoria directa y alternativas: nueva solicitud o desistimiento, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasificar el producto. Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente. Evidencia que debe quedar: Clasificación sustentada.","Verificar el requisito vigente. Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado. Evidencia que debe quedar: Norma citada y vigente.","Preparar la evidencia. Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones. Evidencia que debe quedar: Expediente indexado.","Radicar y responder. Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables. Evidencia que debe quedar: Radicado y respuesta.","Mantener la autorización. Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas. Evidencia que debe quedar: Registro actualizado.","Vigilar el entorno. Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio. Evidencia que debe quedar: Informe de inteligencia regulatoria.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar revocatoria directa y alternativas: nueva solicitud o desistimiento en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Revocatoria directa y alternativas: nueva solicitud o desistimiento»?","respuesta":"Compara la revocatoria directa con los recursos y con la presentación de una nueva solicitud."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Revocatoria directa y alternativas: nueva solicitud o desistimiento se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 5. Notificación, radicación, negaciones y recursos.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Revocatoria directa de los actos administrativos: causales, término y modelo. Gerencie.com (ES)","url":"https://www.gerencie.com/causales-de-revocatoria-directa-de-los-actos-administrativos.html"},{"cita":"[Página web] Concepto INVIMA 2058982 de 2018 – Trámites en curso, requerimiento, negación y abandono. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/concepto_invima_2058982_2018.htm"},{"cita":"[Página web] Concepto INVIMA 1260 de 2020 – Desistimiento de solicitudes de registro sanitario. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/concepto_invima_0001260_2020.htm"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente revocatoria directa y alternativas: nueva solicitud o desistimiento en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de revocatoria directa y alternativas: nueva solicitud o desistimiento"}],"keywords":["curso","respuesta","requerimientos","invima","revocatoria","directa","alternativas","nueva","solicitud","desistimiento","unidad","notificación"],"mapa":{"centro":"Revocatoria directa y alternativas: nueva solicitud o desistimiento","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 5. Notificación, radicación, negaciones y recursos","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Clasificar el producto","Verificar el requisito vigente","Preparar la evidencia"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Clasificación sustentada","Norma citada y vigente","Expediente indexado"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se construye y se sostiene un trámite regulatorio","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Clasificar el producto","detalle":"Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente.","icono":"Search","evidencia":"Clasificación sustentada"},{"titulo":"Verificar el requisito vigente","detalle":"Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado.","icono":"ClipboardList","evidencia":"Norma citada y vigente"},{"titulo":"Preparar la evidencia","detalle":"Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones.","icono":"Workflow","evidencia":"Expediente indexado"},{"titulo":"Radicar y responder","detalle":"Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables.","icono":"FileCheck","evidencia":"Radicado y respuesta"},{"titulo":"Mantener la autorización","detalle":"Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas.","icono":"RefreshCw","evidencia":"Registro actualizado"},{"titulo":"Vigilar el entorno","detalle":"Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio.","icono":"CheckCircle2","evidencia":"Informe de inteligencia regulatoria"}]},"caso":{"titulo":"Revocatoria directa y alternativas: nueva solicitud o desistimiento","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 5. Notificación, radicación, negaciones y recursos: una situación que exige documentar la decisión. La pregunta que decide esta clase es: Un titular dejó vencer el plazo del recurso y pide la revocatoria directa alegando que la negación es contraria a la ley. ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Procede siempre, porque la revocatoria reemplaza el recurso que no se presentó.","correcta":false,"retro":"Tiene causales y límites propios."},{"texto":"No procede nunca contra actos que niegan un registro sanitario.","correcta":false,"retro":"La norma no la excluye por ese motivo."},{"texto":"Procede solo si el titular paga de nuevo la tarifa del trámite.","correcta":false,"retro":"El pago no es una causal."},{"texto":"Puede pedirse por las causales del artículo 93; esa causal no procede si interpuso los recursos.","correcta":true,"retro":"Correcto. Aquí no los interpuso."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 32. Caso práctico: recurso de reposición contra una negación por bioequivalencia
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso práctico: recurso de reposición contra una negación por bioequivalencia$t$
     AND m.title = $u$Unidad 5. Notificación, radicación, negaciones y recursos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso práctico: recurso de reposición contra una negación por bioequivalencia$t$, $u$Unidad 5. Notificación, radicación, negaciones y recursos$u$;
