  -- 07. Caso práctico: revisión del arte de una caja para un nuevo registro sanitario
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso práctico: revisión del arte de una caja para un nuevo registro sanitario$t$
     AND m.title = $u$Unidad 1. Fundamentos y marco normativo del etiquetado de medicamentos en Colombia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso práctico: revisión del arte de una caja para un nuevo registro sanitario$t$, $u$Unidad 1. Fundamentos y marco normativo del etiquetado de medicamentos en Colombia$u$;
