  -- 11. Medicamentos de control especial: franja violeta y situación normativa actual
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Medicamentos de control especial: franja violeta y situación normativa actual$t$
     AND m.title = $u$Unidad 2. Leyendas obligatorias y regímenes especiales de etiquetado$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Medicamentos de control especial: franja violeta y situación normativa actual$t$, $u$Unidad 2. Leyendas obligatorias y regímenes especiales de etiquetado$u$;
