  -- 17. Estructura de la IPP según el instructivo ASS-RSA-IN56
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Estructura de la IPP según el instructivo ASS-RSA-IN56$t$
     AND m.title = $u$Unidad 3. Inserto, información para prescribir (IPP) e información de seguridad$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Estructura de la IPP según el instructivo ASS-RSA-IN56$t$, $u$Unidad 3. Inserto, información para prescribir (IPP) e información de seguridad$u$;
