  -- 25. Estrategias de prevención aplicadas al diseño del empaque
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Estrategias de prevención aplicadas al diseño del empaque$t$
     AND m.title = $u$Unidad 4. Diseño, legibilidad y prevención de errores de medicación$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Estrategias de prevención aplicadas al diseño del empaque$t$, $u$Unidad 4. Diseño, legibilidad y prevención de errores de medicación$u$;
