  -- 27. Publicidad vs. información: Decreto 334 de 2022 y Resolución 1896 de 2023 (visión breve)
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Publicidad vs. información: Decreto 334 de 2022 y Resolución 1896 de 2023 (visión breve)$t$
