       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 05. Guías ICH Q1A(R2) a Q1E y Q5C
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Guías ICH Q1A(R2) a Q1E y Q5C$t$
     AND m.title = $u$Unidad 1. Fundamentos y marco normativo de la estabilidad$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Guías ICH Q1A(R2) a Q1E y Q5C$t$, $u$Unidad 1. Fundamentos y marco normativo de la estabilidad$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Guías ICH Q1A(R2) a Q1E y Q5C","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de guías ICH Q1A(R2) a Q1E y Q5C. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar guías ICH Q1A(R2) a Q1E y Q5C con tus propias palabras y reconocer por qué importa en curso de Estudios de Estabilidad para el Registro de Medicamentos.","Relacionar guías ICH Q1A(R2) a Q1E y Q5C con unidad 1. Fundamentos y marco normativo de la estabilidad y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar guías ICH Q1A(R2) a Q1E y Q5C y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"El estudiante describe el alcance de cada guía ICH de estabilidad (Q1A(R2) general, Q1B fotoestabilidad, Q1C nuevas formas, Q1D diseños reducidos, Q1E evaluación de datos, Q5C biotecnológicos) y cómo se usan como soporte en Colombia."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, guías ICH Q1A(R2) a Q1E y Q5C aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos y marco normativo de la estabilidad. El objetivo del curso es claro: Capacitar al químico farmacéutico para diseñar protocolos de estabilidad conformes a la normativa colombiana y a las guías internacionales, evaluar estadísticamente los datos para asignar la vida útil, y presentar y defender la información de estabilidad en los trámites de registro, renovación y modificación ante el INVIMA. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: El estudiante describe el alcance de cada guía ICH de estabilidad (Q1A(R2) general, Q1B fotoestabilidad, Q1C nuevas formas, Q1D diseños reducidos, Q1E evaluación de datos, Q5C biotecnológicos) y cómo se usan como soporte en Colombia.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. Fundamentos y marco normativo de la estabilidad y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de normas aplicables con análisis.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar guías ICH Q1A(R2) a Q1E y Q5C, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Para cada trámite, identifica la norma colombiana aplicable y el artículo que lo sustenta. Evidencia que debe quedar: Registro del paso.","Define la condición de largo plazo exigida para Colombia. Evidencia que debe quedar: Registro del paso.","Indica qué guías ICH u OMS pueden usarse como soporte. Evidencia que debe quedar: Registro del paso.","Analiza qué exige el cambio de envase primario en términos de estabilidad. Evidencia que debe quedar: Registro del paso.","Resume los riesgos de requerimiento de cada trámite. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar guías ICH Q1A(R2) a Q1E y Q5C en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Guías ICH Q1A(R2) a Q1E y Q5C»?","respuesta":"El estudiante describe el alcance de cada guía ICH de estabilidad (Q1A(R2) general, Q1B fotoestabilidad, Q1C nuevas formas, Q1D diseños reducidos, Q1E evaluación de datos, Q5C biotecnológicos) y cómo se usan como soporte en Colombia."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de normas aplicables con análisis.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Guías ICH Q1A(R2) a Q1E y Q5C se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos y marco normativo de la estabilidad.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Curso ICH – Clase 03: Guía ICH Q1A(R2): Pruebas de Estabilidad para Nuevos Fármacos y Productos","url":"https://www.youtube.com/watch?v=GMuRFKpWDXE"},{"cita":"[Página web] ICH Q1A (R2) Stability testing of new drug substances and drug products – Scientific guideline. EMA (EN) · mismo documento, versión en inglés del sitio","url":"https://www.ema.europa.eu/en/ich-q1a-r2-stability-testing-new-drug-substances-drug-products-scientific-guideline"},{"cita":"Quality of Biotechnological Products: Stability Testing of Biotechnological/Biological Products (ICH Q5C). EMA / ICH (EN)","url":"https://www.ema.europa.eu/en/documents/scientific-guideline/quality-biotechnological-products-stability-testing-biotechnological/biological-products_en.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente guías ICH Q1A(R2) a Q1E y Q5C en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de guías ICH Q1A(R2) a Q1E y Q5C"}],"keywords":["curso","estudios","estabilidad","registro","medicamentos","guías","unidad","fundamentos","marco","normativo"],"mapa":{"centro":"Guías ICH Q1A(R2) a Q1E y Q5C","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. Fundamentos y marco normativo de la estabilidad","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Norma de estabilidad aplicable a distintos trámites","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Para cada trámite, identifica la norma colombiana aplicable y el artículo que lo sustenta.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Define la condición de largo plazo exigida para Colombia.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica qué guías ICH u OMS pueden usarse como soporte.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza qué exige el cambio de envase primario en términos de estabilidad.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Resume los riesgos de requerimiento de cada trámite.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Norma de estabilidad aplicable a distintos trámites","contexto":"El área regulatoria de Farmacéutica Andina (ficticia) prepara cinco trámites (datos simulados): (1) registro nuevo de cápsulas de omeprazol fabricadas en Colombia; (2) renovación de un jarabe de síntesis química; (3) modificación por cambio de envase primario de un colirio; (4) registro de un fitoterapéutico en cápsulas; (5) registro de una insulina importada.","pregunta":"¿Qué decisión demuestra que entendiste guías ICH Q1A(R2) a Q1E y Q5C?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
