   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Estudios de estrés y degradación forzada$t$
     AND m.title = $u$Unidad 3. Diseño del protocolo y métodos indicadores de estabilidad$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Estudios de estrés y degradación forzada$t$, $u$Unidad 3. Diseño del protocolo y métodos indicadores de estabilidad$u$;
