     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 26. Estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016$t$
     AND m.title = $u$Unidad 4. Evaluación estadística y asignación de vida útil$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016$t$, $u$Unidad 4. Evaluación estadística y asignación de vida útil$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016 con tus propias palabras y reconocer por qué importa en curso de Estudios de Estabilidad para el Registro de Medicamentos.","Relacionar estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016 con unidad 4. Evaluación estadística y asignación de vida útil y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016 y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"El estudiante compara los requisitos de estabilidad de biológicos (potencia, agregados, cadena de frío, estabilidad natural, salidas accidentales de temperatura) con los de síntesis química."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016 aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Evaluación estadística y asignación de vida útil. El objetivo del curso es claro: Capacitar al químico farmacéutico para diseñar protocolos de estabilidad conformes a la normativa colombiana y a las guías internacionales, evaluar estadísticamente los datos para asignar la vida útil, y presentar y defender la información de estabilidad en los trámites de registro, renovación y modificación ante el INVIMA. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: El estudiante compara los requisitos de estabilidad de biológicos (potencia, agregados, cadena de frío, estabilidad natural, salidas accidentales de temperatura) con los de síntesis química.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 4. Evaluación estadística y asignación de vida útil y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de evaluación estadística con propuesta de vida útil.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Calcula la pendiente de cada lote (puedes usar una hoja de cálculo). Evidencia que debe quedar: Registro del paso.","Analiza si los lotes son combinables según ICH Q1E. Evidencia que debe quedar: Registro del paso.","Estima el tiempo en que el límite inferior de confianza del 95 % cruza 95,0 %. Evidencia que debe quedar: Registro del paso.","Aplica el límite de extrapolación de ICH Q1E a los 12 meses disponibles. Evidencia que debe quedar: Registro del paso.","Propón la vida útil, la leyenda de almacenamiento y el compromiso de estabilidad. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016 en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016»?","respuesta":"El estudiante compara los requisitos de estabilidad de biológicos (potencia, agregados, cadena de frío, estabilidad natural, salidas accidentales de temperatura) con los de síntesis química."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de evaluación estadística con propuesta de vida útil.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016 se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Evaluación estadística y asignación de vida útil.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Quality of Biotechnological Products: Stability Testing of Biotechnological/Biological Products (ICH Q5C). EMA / ICH (EN)","url":"https://www.ema.europa.eu/en/documents/scientific-guideline/quality-biotechnological-products-stability-testing-biotechnological/biological-products_en.pdf"},{"cita":"[Página web] Resolución 3690 de 2016 – Guía de Estabilidad de Medicamentos Biológicos. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3690_2016.htm"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016 en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016"}],"keywords":["curso","estudios","estabilidad","registro","medicamentos","biológicos","resolución","unidad","evaluación","estadística","asignación"],"mapa":{"centro":"Estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 4. Evaluación estadística y asignación de vida útil","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Cálculo de la vida útil con datos de tres lotes","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Calcula la pendiente de cada lote (puedes usar una hoja de cálculo).","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Analiza si los lotes son combinables según ICH Q1E.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Estima el tiempo en que el límite inferior de confianza del 95 % cruza 95,0 %.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Aplica el límite de extrapolación de ICH Q1E a los 12 meses disponibles.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propón la vida útil, la leyenda de almacenamiento y el compromiso de estabilidad.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Cálculo de la vida útil con datos de tres lotes","contexto":"Laboratorios Meridiano (ficticia) tiene datos de valoración de tres lotes de tabletas a 30 °C/75 % HR (datos simulados), criterio de aceptación 95,0 % a 105,0 %. Lote A: 100,2 / 99,6 / 99,1 / 98,5 / 97,9 % a 0, 3, 6, 9 y 12 meses. Lote B: 100,5 / 99,9 / 99,3 / 98,8 / 98,2 %. Lote C: 99,8 / 99,0 / 98,1 / 97,3 / 96,4 %. El acelerado a 6 meses no mostró cambio significativo. Se propone una vida útil de 30 meses.","pregunta":"¿Qué decisión demuestra que entendiste estabilidad de biológicos: ICH Q5C y Resolución 3690 de 2016?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 27. Introducción a la unidad: la estabilidad después de la aprobación
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción a la unidad: la estabilidad después de la aprobación$t$
     AND m.title = $u$Unidad 5. Ciclo de vida, dossier y requerimientos INVIMA$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción a la unidad: la estabilidad después de la aprobación$t$, $u$Unidad 5. Ciclo de vida, dossier y requerimientos INVIMA$u$;
