  -- 02. Biodisponibilidad y bioequivalencia: definiciones y bases farmacocinéticas
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Biodisponibilidad y bioequivalencia: definiciones y bases farmacocinéticas$t$
     AND m.title = $u$Unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Biodisponibilidad y bioequivalencia: definiciones y bases farmacocinéticas$t$, $u$Unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad$u$;
