              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 06. Caso: selección y soporte documental del comparador
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: selección y soporte documental del comparador$t$
     AND m.title = $u$Unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: selección y soporte documental del comparador$t$, $u$Unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso: selección y soporte documental del comparador","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de caso: selección y soporte documental del comparador. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso: selección y soporte documental del comparador con tus propias palabras y reconocer por qué importa en curso de Bioequivalencia y Requisitos Regulatorios en Colombia.","Relacionar caso: selección y soporte documental del comparador con unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso: selección y soporte documental del comparador y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Ejecuta la selección y documentación del producto de referencia para un estudio que se presentará al INVIMA. que el estudiante seleccione y documente correctamente el producto de referencia (comparador) de un estudio de bioequivalencia que se presentará al INVIMA. el producto de referencia es aquel con el que se compara el medicamento multifuente; por regla general es el innovador que desarrolló la investigación clínica y cuya eficacia y seguridad están demostradas. La Resolución 1124 de 2016 (Anexo técnico 2,…"},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, caso: selección y soporte documental del comparador aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad. El objetivo del curso es claro: Que el químico farmacéutico determine cuándo un medicamento requiere estudio de bioequivalencia o bioexención, interprete el diseño y los resultados de un estudio y prepare y defienda ante el INVIMA la documentación de BD/BE conforme a la normativa vigente. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Ejecuta la selección y documentación del producto de referencia para un estudio que se presentará al INVIMA. que el estudiante seleccione y documente correctamente el producto de referencia (comparador) de un estudio de bioequivalencia que se presentará al INVIMA. el producto de referencia es aquel con el que se compara el medicamento multifuente; por regla general es el innovador que desarrolló la investigación clínica y cuya eficacia y seguridad están demostradas. La Resolución 1124 de 2016 (Anexo técnico 2,…","Una pregunta que se usa para comprobar esta clase es: «Para un estudio que se presentará al Invima, un patrocinador propone usar como comparador el genérico más vendido del país. ¿Cuál es la mejor valoración?» La respuesta correcta se apoya en lo siguiente: El anexo técnico 2 de la Resolución 1124 de 2016 lista los medicamentos que deben presentar bioequivalencia con sus comparadores de referencia; por regla general es el innovador. Un comparador distinto puede invalidar el estudio. La fuente citada es: Resolución 1124 de 2016, arts. 2 y 12, anexo técnico 2.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de decisiones con fundamento normativo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso: selección y soporte documental del comparador, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Revisa el artículo 2 de la Resolución 1124 de 2016 y sus parágrafos. Evidencia que debe quedar: Registro del paso.","Decide para cada caso si se requiere estudio de BE. Evidencia que debe quedar: Registro del paso.","Analiza si alguna forma farmacéutica podría justificar una bioexención. Evidencia que debe quedar: Registro del paso.","Explica qué pasa con la renovación de estudios ya aprobados. Evidencia que debe quedar: Registro del paso.","Indica dónde consultar el listado vigente y el comparador. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso: selección y soporte documental del comparador en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso: selección y soporte documental del comparador»?","respuesta":"Ejecuta la selección y documentación del producto de referencia para un estudio que se presentará al INVIMA. que el estudiante seleccione y documente correctamente el producto de referencia (comparador) de un estudio de bioequivalencia que se presentará al INVIMA. el producto de referencia es aquel con el que se compara el medicamento multifuente; por regla general es el innovador que desarrolló la investigación clínica y cuya eficacia y seguridad están demostradas. La Resolución 1124 de 2016 (Anexo técnico 2,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de decisiones con fundamento normativo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Caso: selección y soporte documental del comparador se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso: selección y soporte documental del comparador en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de caso: selección y soporte documental del comparador"}],"keywords":["curso","bioequivalencia","requisitos","regulatorios","colombia","selección","soporte","documental","comparador","unidad","fundamentos","biodisponibilidad"],"mapa":{"centro":"Caso: selección y soporte documental del comparador","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: ¿Requiere estudio de bioequivalencia?","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Revisa el artículo 2 de la Resolución 1124 de 2016 y sus parágrafos.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Decide para cada caso si se requiere estudio de BE.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Analiza si alguna forma farmacéutica podría justificar una bioexención.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Explica qué pasa con la renovación de estudios ya aprobados.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Indica dónde consultar el listado vigente y el comparador.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Caso: selección y soporte documental del comparador","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. Fundamentos de biodisponibilidad, bioequivalencia e intercambiabilidad: Farmacéutica Sabana (ficticia) revisa su portafolio (datos simulados): (1) registro nuevo de tabletas de un principio activo incluido en el anexo técnico 2; (2) renovación de un producto cuyos estudios de BE ya fueron aprobados en el registro inicial; (3) modificación por cambio de fabricante del principio activo de un producto del listado; (4) registro de un biosimilar; (5) registro de una solución oral de un principio activo del listado. La pregunta que decide esta clase es: Para un estudio que se presentará al Invima, un patrocinador propone usar como comparador el genérico más vendido del país. ¿Cuál es la mejor valoración?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es adecuado, porque el producto más vendido es el que más usan los pacientes en la práctica diaria.","correcta":false,"retro":"Las ventas no definen el comparador."},{"texto":"Es adecuado si el genérico ya tiene registro sanitario vigente en Colombia.","correcta":false,"retro":"El registro no lo convierte en referencia."},{"texto":"Es indiferente, porque el Invima acepta cualquier comparador con registro.","correcta":false,"retro":"El comparador está definido."},{"texto":"No: se usa el producto de referencia del listado del Invima, con su soporte documental.","correcta":true,"retro":"Correcto. Un comparador errado invalida el estudio."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 07. Introducción a la unidad: normas e instituciones de la BE en Colombia
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción a la unidad: normas e instituciones de la BE en Colombia$t$
     AND m.title = $u$Unidad 2. Marco regulatorio colombiano de BD/BE$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción a la unidad: normas e instituciones de la BE en Colombia$t$, $u$Unidad 2. Marco regulatorio colombiano de BD/BE$u$;
