     AND l.title = $t$Guías de la EMA y la FDA: similitudes y diferencias$t$
     AND m.title = $u$Unidad 3. Referentes internacionales y diseño de estudios de BE$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Guías de la EMA y la FDA: similitudes y diferencias$t$, $u$Unidad 3. Referentes internacionales y diseño de estudios de BE$u$;
