    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 33. Caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE$t$
     AND m.title = $u$Unidad 5. Presentación de estudios al INVIMA y requerimientos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE$t$, $u$Unidad 5. Presentación de estudios al INVIMA y requerimientos$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE con tus propias palabras y reconocer por qué importa en curso de Bioequivalencia y Requisitos Regulatorios en Colombia.","Relacionar caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE con unidad 5. Presentación de estudios al INVIMA y requerimientos y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Ejecuta la respuesta estructurada a un auto de requerimiento con soportes trazables. analizar y responder un requerimiento del INVIMA relacionado con un estudio de bioequivalencia, dentro del plazo y con soportes completos. cuando el evaluador encuentra deficiencias en un estudio de BD/BE presentado con una solicitud de registro, renovación o modificación, emite un auto de requerimiento. El titular debe responder punto por punto y en el plazo otorgado; si no responde o la respuesta es insuficiente, la solicitud puede negarse o entenderse desistida.…"},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 5. Presentación de estudios al INVIMA y requerimientos. El objetivo del curso es claro: Que el químico farmacéutico determine cuándo un medicamento requiere estudio de bioequivalencia o bioexención, interprete el diseño y los resultados de un estudio y prepare y defienda ante el INVIMA la documentación de BD/BE conforme a la normativa vigente. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Ejecuta la respuesta estructurada a un auto de requerimiento con soportes trazables. analizar y responder un requerimiento del INVIMA relacionado con un estudio de bioequivalencia, dentro del plazo y con soportes completos. cuando el evaluador encuentra deficiencias en un estudio de BD/BE presentado con una solicitud de registro, renovación o modificación, emite un auto de requerimiento. El titular debe responder punto por punto y en el plazo otorgado; si no responde o la respuesta es insuficiente, la solicitud puede negarse o entenderse desistida.…","Una pregunta que se usa para comprobar esta clase es: «Un estudio obtuvo un IC 90 % de Cmax de 78-118 %. El patrocinador propone excluir dos voluntarios «atípicos» para que cumpla. ¿Cuál es la mejor valoración?» La respuesta correcta se apoya en lo siguiente: Las exclusiones de sujetos deben definirse en el protocolo y basarse en criterios previos (por ejemplo, vómito o desviaciones), no en el resultado farmacocinético. Excluir datos para cumplir el criterio sesga el estudio y genera rechazo. La fuente citada es: OMS TRS 1003, anexo 6; guía de BE de la EMA.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 5. Presentación de estudios al INVIMA y requerimientos y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasificar el producto. Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente. Evidencia que debe quedar: Clasificación sustentada.","Verificar el requisito vigente. Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado. Evidencia que debe quedar: Norma citada y vigente.","Preparar la evidencia. Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones. Evidencia que debe quedar: Expediente indexado.","Radicar y responder. Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables. Evidencia que debe quedar: Radicado y respuesta.","Mantener la autorización. Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas. Evidencia que debe quedar: Registro actualizado.","Vigilar el entorno. Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio. Evidencia que debe quedar: Informe de inteligencia regulatoria.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Un titular ficticio recibió requerimientos en tres estudios de BE (datos simulados): comparador sin soportes de compra, falta de validación bioanalítica y exclusiones de voluntarios no previstas en el protocolo. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE»?","respuesta":"Ejecuta la respuesta estructurada a un auto de requerimiento con soportes trazables. analizar y responder un requerimiento del INVIMA relacionado con un estudio de bioequivalencia, dentro del plazo y con soportes completos. cuando el evaluador encuentra deficiencias en un estudio de BD/BE presentado con una solicitud de registro, renovación o modificación, emite un auto de requerimiento. El titular debe responder punto por punto y en el plazo otorgado; si no responde o la respuesta es insuficiente, la solicitud puede negarse o entenderse desistida.…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 5. Presentación de estudios al INVIMA y requerimientos.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE"}],"keywords":["curso","bioequivalencia","requisitos","regulatorios","colombia","respuesta","requerimiento","invima","sobre","estudio","unidad","presentación"],"mapa":{"centro":"Caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 5. Presentación de estudios al INVIMA y requerimientos","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Clasificar el producto","Verificar el requisito vigente","Preparar la evidencia"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Clasificación sustentada","Norma citada y vigente","Expediente indexado"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se construye y se sostiene un trámite regulatorio","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Clasificar el producto","detalle":"Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente.","icono":"Search","evidencia":"Clasificación sustentada"},{"titulo":"Verificar el requisito vigente","detalle":"Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado.","icono":"ClipboardList","evidencia":"Norma citada y vigente"},{"titulo":"Preparar la evidencia","detalle":"Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones.","icono":"Workflow","evidencia":"Expediente indexado"},{"titulo":"Radicar y responder","detalle":"Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables.","icono":"FileCheck","evidencia":"Radicado y respuesta"},{"titulo":"Mantener la autorización","detalle":"Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas.","icono":"RefreshCw","evidencia":"Registro actualizado"},{"titulo":"Vigilar el entorno","detalle":"Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio.","icono":"CheckCircle2","evidencia":"Informe de inteligencia regulatoria"}]},"caso":{"titulo":"Caso: respuesta a un requerimiento del INVIMA sobre un estudio de BE","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 5. Presentación de estudios al INVIMA y requerimientos: una situación que exige documentar la decisión. La pregunta que decide esta clase es: Un estudio obtuvo un IC 90 % de Cmax de 78-118 %. El patrocinador propone excluir dos voluntarios «atípicos» para que cumpla. ¿Cuál es la mejor valoración?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es aceptable, porque los datos atípicos siempre deben excluirse del análisis.","correcta":false,"retro":"Las exclusiones se definen antes."},{"texto":"Es aceptable si el comité de ética lo aprueba después de ver los resultados.","correcta":false,"retro":"No se justifica tras ver los resultados."},{"texto":"Es aceptable si los voluntarios excluidos tuvieron concentraciones bajas.","correcta":false,"retro":"Excluir por resultado sesga el estudio."},{"texto":"No es aceptable: las exclusiones deben estar previstas en el protocolo y justificarse sin ver el resultado.","correcta":true,"retro":"Correcto. Lo contrario sesga la conclusión."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 34. Caso integrador: expediente de BE para un registro sanitario nuevo
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso integrador: expediente de BE para un registro sanitario nuevo$t$
     AND m.title = $u$Unidad 5. Presentación de estudios al INVIMA y requerimientos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso integrador: expediente de BE para un registro sanitario nuevo$t$, $u$Unidad 5. Presentación de estudios al INVIMA y requerimientos$u$;
