  END IF;

  -- 09. Notificación de actos administrativos: electrónica, personal, por autorizado y por aviso
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Notificación de actos administrativos: electrónica, personal, por autorizado y por aviso$t$
     AND m.title = $u$Unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Notificación de actos administrativos: electrónica, personal, por autorizado y por aviso$t$, $u$Unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Notificación de actos administrativos: electrónica, personal, por autorizado y por aviso","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de notificación de actos administrativos: electrónica, personal, por autorizado y por aviso. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar notificación de actos administrativos: electrónica, personal, por autorizado y por aviso con tus propias palabras y reconocer por qué importa en curso de Gestión Documental de Trámites ante el INVIMA.","Relacionar notificación de actos administrativos: electrónica, personal, por autorizado y por aviso con unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar notificación de actos administrativos: electrónica, personal, por autorizado y por aviso y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta las modalidades de notificación de autos y resoluciones y cómo autorizar a un tercero para notificarse."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, notificación de actos administrativos: electrónica, personal, por autorizado y por aviso aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA. El objetivo del curso es claro: Que el estudiante gestione de forma trazable, oportuna y sin rechazos la documentación de los trámites de medicamentos ante el INVIMA, desde la obtención y legalización de documentos hasta la radicación, el seguimiento, el archivo y el control de vencimientos del portafolio. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta las modalidades de notificación de autos y resoluciones y cómo autorizar a un tercero para notificarse.","Una pregunta que se usa para comprobar esta clase es: «La empresa aceptó la notificación electrónica. ¿Desde cuándo corre el plazo de un auto notificado así?» La respuesta correcta se apoya en lo siguiente: Según el artículo 56 del CPACA, la notificación electrónica queda surtida a partir de la fecha y hora en que el administrado accede a ella, lo que certifica la administración. El plazo del auto corre desde entonces. La fuente citada es: Ley 1437 de 2011, art. 56.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de auditoría con plan de acción.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar notificación de actos administrativos: electrónica, personal, por autorizado y por aviso, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Diseña la tabla de cruce (registro, titular, estado, CUM, resoluciones). Evidencia que debe quedar: Registro del paso.","Clasifica cada discrepancia por riesgo (alto, medio, bajo). Evidencia que debe quedar: Registro del paso.","Define la acción para cada una y su responsable. Evidencia que debe quedar: Registro del paso.","Analiza la causa raíz común de las discrepancias. Evidencia que debe quedar: Registro del paso.","Propón un procedimiento de auditoría periódica. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar notificación de actos administrativos: electrónica, personal, por autorizado y por aviso en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Notificación de actos administrativos: electrónica, personal, por autorizado y por aviso»?","respuesta":"Interpreta las modalidades de notificación de autos y resoluciones y cómo autorizar a un tercero para notificarse."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de auditoría con plan de acción.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Notificación de actos administrativos: electrónica, personal, por autorizado y por aviso se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Preguntas frecuentes - Atención al ciudadano INVIMA. INVIMA (ES)","url":"https://www.invima.gov.co/atencion-al-ciudadano/preguntas-frecuentes"},{"cita":"[Página web] Consultas, registros y documentos asociados - INVIMA (radicaciones, resoluciones por notificar, notificación por aviso). INVIMA (ES)","url":"https://www.invima.gov.co/tramites-y-servicios/consultas-registros-documentos-asociados"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente notificación de actos administrativos: electrónica, personal, por autorizado y por aviso en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de notificación de actos administrativos: electrónica, personal, por autorizado y por aviso"}],"keywords":["curso","gestión","documental","trámites","invima","notificación","actos","administrativos","electrónica","personal","autorizado","aviso"],"mapa":{"centro":"Notificación de actos administrativos: electrónica, personal, por autorizado y por aviso","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Auditoría documental de un portafolio con bases públicas","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Diseña la tabla de cruce (registro, titular, estado, CUM, resoluciones).","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica cada discrepancia por riesgo (alto, medio, bajo).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Define la acción para cada una y su responsable.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza la causa raíz común de las discrepancias.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propón un procedimiento de auditoría periódica.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Notificación de actos administrativos: electrónica, personal, por autorizado y por aviso","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA: Laboratorios Ribera (ficticia) tiene una hoja de cálculo con 10 registros (datos simulados). Al cruzarla con las bases públicas encuentras: dos registros con titular distinto al de la hoja (hubo una cesión hace un año); un CUM de una presentación que figura como no vigente; un registro con una modificación aprobada que no está en el archivo; y una resolución de renovación cuya copia interna no coincide con la descargada del Invima. La pregunta que decide esta clase es: La empresa aceptó la notificación electrónica. ¿Desde cuándo corre el plazo de un auto notificado así?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Desde la fecha de firma del auto por el funcionario del Invima que lo expide en el trámite.","correcta":false,"retro":"La firma no es la notificación."},{"texto":"Desde que el administrado accede a ella, según lo certifique la administración.","correcta":true,"retro":"Correcto. Por eso se revisa el buzón a diario."},{"texto":"Desde que el jefe de regulatorios imprime el auto.","correcta":false,"retro":"Imprimir no es el criterio."},{"texto":"Desde 30 días después del envío, se lea o no.","correcta":false,"retro":"No es la regla del artículo 56."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 10. Consulta de registros sanitarios: básica, avanzada e InvimÁgil
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Consulta de registros sanitarios: básica, avanzada e InvimÁgil$t$
     AND m.title = $u$Unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Consulta de registros sanitarios: básica, avanzada e InvimÁgil$t$, $u$Unidad 2. Seguimiento de trámites, notificaciones y bases de datos públicas del INVIMA$u$;
