       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 15. Certificado de existencia y representación legal: obtención electrónica y verificación en RUES
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Certificado de existencia y representación legal: obtención electrónica y verificación en RUES$t$
     AND m.title = $u$Unidad 3. Documentos legales, apostilla, legalización y traducción oficial$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Certificado de existencia y representación legal: obtención electrónica y verificación en RUES$t$, $u$Unidad 3. Documentos legales, apostilla, legalización y traducción oficial$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Certificado de existencia y representación legal: obtención electrónica y verificación en RUES","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de certificado de existencia y representación legal: obtención electrónica y verificación en RUES. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar certificado de existencia y representación legal: obtención electrónica y verificación en RUES con tus propias palabras y reconocer por qué importa en curso de Gestión Documental de Trámites ante el INVIMA.","Relacionar certificado de existencia y representación legal: obtención electrónica y verificación en RUES con unidad 3. Documentos legales, apostilla, legalización y traducción oficial y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar certificado de existencia y representación legal: obtención electrónica y verificación en RUES y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe cómo obtener el certificado electrónico de Cámara de Comercio, su validez jurídica y su verificación con código en RUES."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, certificado de existencia y representación legal: obtención electrónica y verificación en RUES aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Documentos legales, apostilla, legalización y traducción oficial. El objetivo del curso es claro: Que el estudiante gestione de forma trazable, oportuna y sin rechazos la documentación de los trámites de medicamentos ante el INVIMA, desde la obtención y legalización de documentos hasta la radicación, el seguimiento, el archivo y el control de vencimientos del portafolio. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe cómo obtener el certificado electrónico de Cámara de Comercio, su validez jurídica y su verificación con código en RUES.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 3. Documentos legales, apostilla, legalización y traducción oficial y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar certificado de existencia y representación legal: obtención electrónica y verificación en RUES, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasificar el producto. Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente. Evidencia que debe quedar: Clasificación sustentada.","Verificar el requisito vigente. Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado. Evidencia que debe quedar: Norma citada y vigente.","Preparar la evidencia. Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones. Evidencia que debe quedar: Expediente indexado.","Radicar y responder. Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables. Evidencia que debe quedar: Radicado y respuesta.","Mantener la autorización. Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas. Evidencia que debe quedar: Registro actualizado.","Vigilar el entorno. Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio. Evidencia que debe quedar: Informe de inteligencia regulatoria.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar certificado de existencia y representación legal: obtención electrónica y verificación en RUES en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Certificado de existencia y representación legal: obtención electrónica y verificación en RUES»?","respuesta":"Describe cómo obtener el certificado electrónico de Cámara de Comercio, su validez jurídica y su verificación con código en RUES."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Certificado de existencia y representación legal: obtención electrónica y verificación en RUES se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Documentos legales, apostilla, legalización y traducción oficial.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Certificados electrónicos de las Cámaras de Comercio: validez y verificación en RUES. Cámara de Comercio de Cartagena (ES)","url":"https://mail.cccartagena.org.co/sites/default/files/media/preguntas/prf_Certificados-Electronicos_0.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente certificado de existencia y representación legal: obtención electrónica y verificación en RUES en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de certificado de existencia y representación legal: obtención electrónica y verificación en RUES"}],"keywords":["curso","gestión","documental","trámites","invima","certificado","existencia","representación","legal","obtención","electrónica","verificación"],"mapa":{"centro":"Certificado de existencia y representación legal: obtención electrónica y verificación en RUES","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 3. Documentos legales, apostilla, legalización y traducción oficial","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Clasificar el producto","Verificar el requisito vigente","Preparar la evidencia"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Clasificación sustentada","Norma citada y vigente","Expediente indexado"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se construye y se sostiene un trámite regulatorio","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Clasificar el producto","detalle":"Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente.","icono":"Search","evidencia":"Clasificación sustentada"},{"titulo":"Verificar el requisito vigente","detalle":"Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado.","icono":"ClipboardList","evidencia":"Norma citada y vigente"},{"titulo":"Preparar la evidencia","detalle":"Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones.","icono":"Workflow","evidencia":"Expediente indexado"},{"titulo":"Radicar y responder","detalle":"Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables.","icono":"FileCheck","evidencia":"Radicado y respuesta"},{"titulo":"Mantener la autorización","detalle":"Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas.","icono":"RefreshCw","evidencia":"Registro actualizado"},{"titulo":"Vigilar el entorno","detalle":"Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio.","icono":"CheckCircle2","evidencia":"Informe de inteligencia regulatoria"}]},"caso":{"titulo":"Certificado de existencia y representación legal: obtención electrónica y verificación en RUES","contexto":"Un importador ficticio debe renovar un registro con documentos de un fabricante en un país parte de la Convención de La Haya y de otro que no lo es (datos simulados). Faltan cinco semanas para radicar y nadie ha iniciado el trámite de los documentos.","pregunta":"¿Qué decisión demuestra que entendiste certificado de existencia y representación legal: obtención electrónica y verificación en RUES?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 16. Poderes y cartas de autorización para trámites ante el INVIMA
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Poderes y cartas de autorización para trámites ante el INVIMA$t$
     AND m.title = $u$Unidad 3. Documentos legales, apostilla, legalización y traducción oficial$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Poderes y cartas de autorización para trámites ante el INVIMA$t$, $u$Unidad 3. Documentos legales, apostilla, legalización y traducción oficial$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Poderes y cartas de autorización para trámites ante el INVIMA","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de poderes y cartas de autorización para trámites ante el INVIMA. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar poderes y cartas de autorización para trámites ante el INVIMA con tus propias palabras y reconocer por qué importa en curso de Gestión Documental de Trámites ante el INVIMA.","Relacionar poderes y cartas de autorización para trámites ante el INVIMA con unidad 3. Documentos legales, apostilla, legalización y traducción oficial y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar poderes y cartas de autorización para trámites ante el INVIMA y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Redacta poderes especiales y cartas de autorización con objeto y facultades correctas para radicar, notificarse y recurrir. identificar cuándo se necesita un poder o una carta de autorización en los trámites ante el INVIMA y redactarlos sin errores que generen requerimientos o rechazos. en los trámites sanitarios actúan tres figuras. El titular del registro sanitario es la persona natural o jurídica a cuyo nombre se expide el registro. El apoderado es quien actúa en nombre del titular ante el INVIMA;…"},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, poderes y cartas de autorización para trámites ante el INVIMA aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Documentos legales, apostilla, legalización y traducción oficial. El objetivo del curso es claro: Que el estudiante gestione de forma trazable, oportuna y sin rechazos la documentación de los trámites de medicamentos ante el INVIMA, desde la obtención y legalización de documentos hasta la radicación, el seguimiento, el archivo y el control de vencimientos del portafolio. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Redacta poderes especiales y cartas de autorización con objeto y facultades correctas para radicar, notificarse y recurrir. identificar cuándo se necesita un poder o una carta de autorización en los trámites ante el INVIMA y redactarlos sin errores que generen requerimientos o rechazos. en los trámites sanitarios actúan tres figuras. El titular del registro sanitario es la persona natural o jurídica a cuyo nombre se expide el registro. El apoderado es quien actúa en nombre del titular ante el INVIMA;…","Una pregunta que se usa para comprobar esta clase es: «Un poder dice «para radicar el trámite de renovación». El Invima notifica un auto al apoderado. ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: Un poder especial se limita a las facultades que expresa. Para un trámite completo conviene incluir radicar, notificarse, responder requerimientos, desistir y recurrir. Revisar las facultades antes de radicar evita problemas en la notificación. La fuente citada es: Código General del Proceso (poderes); buenas prácticas de gestión regulatoria.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Documentos legales, apostilla, legalización y traducción oficial y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar poderes y cartas de autorización para trámites ante el INVIMA, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasificar el producto. Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente. Evidencia que debe quedar: Clasificación sustentada.","Verificar el requisito vigente. Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado. Evidencia que debe quedar: Norma citada y vigente.","Preparar la evidencia. Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones. Evidencia que debe quedar: Expediente indexado.","Radicar y responder. Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables. Evidencia que debe quedar: Radicado y respuesta.","Mantener la autorización. Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas. Evidencia que debe quedar: Registro actualizado.","Vigilar el entorno. Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio. Evidencia que debe quedar: Informe de inteligencia regulatoria.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar poderes y cartas de autorización para trámites ante el INVIMA en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Poderes y cartas de autorización para trámites ante el INVIMA»?","respuesta":"Redacta poderes especiales y cartas de autorización con objeto y facultades correctas para radicar, notificarse y recurrir. identificar cuándo se necesita un poder o una carta de autorización en los trámites ante el INVIMA y redactarlos sin errores que generen requerimientos o rechazos. en los trámites sanitarios actúan tres figuras. El titular del registro sanitario es la persona natural o jurídica a cuyo nombre se expide el registro. El apoderado es quien actúa en nombre del titular ante el INVIMA;…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Poderes y cartas de autorización para trámites ante el INVIMA se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Documentos legales, apostilla, legalización y traducción oficial.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente poderes y cartas de autorización para trámites ante el INVIMA en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de poderes y cartas de autorización para trámites ante el INVIMA"}],"keywords":["curso","gestión","documental","trámites","invima","poderes","cartas","autorización","unidad","documentos","legales","apostilla"],"mapa":{"centro":"Poderes y cartas de autorización para trámites ante el INVIMA","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 3. Documentos legales, apostilla, legalización y traducción oficial","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Clasificar el producto","Verificar el requisito vigente","Preparar la evidencia"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Clasificación sustentada","Norma citada y vigente","Expediente indexado"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se construye y se sostiene un trámite regulatorio","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Clasificar el producto","detalle":"Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente.","icono":"Search","evidencia":"Clasificación sustentada"},{"titulo":"Verificar el requisito vigente","detalle":"Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado.","icono":"ClipboardList","evidencia":"Norma citada y vigente"},{"titulo":"Preparar la evidencia","detalle":"Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones.","icono":"Workflow","evidencia":"Expediente indexado"},{"titulo":"Radicar y responder","detalle":"Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables.","icono":"FileCheck","evidencia":"Radicado y respuesta"},{"titulo":"Mantener la autorización","detalle":"Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas.","icono":"RefreshCw","evidencia":"Registro actualizado"},{"titulo":"Vigilar el entorno","detalle":"Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio.","icono":"CheckCircle2","evidencia":"Informe de inteligencia regulatoria"}]},"caso":{"titulo":"Poderes y cartas de autorización para trámites ante el INVIMA","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 3. Documentos legales, apostilla, legalización y traducción oficial: una situación que exige documentar la decisión. La pregunta que decide esta clase es: Un poder dice «para radicar el trámite de renovación». El Invima notifica un auto al apoderado. ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"El apoderado puede hacer cualquier gestión, porque el poder es general.","correcta":false,"retro":"El poder especial se limita a sus facultades."},{"texto":"El poder no incluye facultades para notificarse ni para recurrir; conviene incluirlas expresamente.","correcta":true,"retro":"Correcto. Se revisan las facultades antes de radicar."},{"texto":"El poder no sirve para nada, porque debe ser otorgado ante notario en el exterior.","correcta":false,"retro":"No es el problema principal."},{"texto":"El poder vence automáticamente al radicar el trámite.","correcta":false,"retro":"No es una regla general."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 17. Certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre$t$
     AND m.title = $u$Unidad 3. Documentos legales, apostilla, legalización y traducción oficial$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre$t$, $u$Unidad 3. Documentos legales, apostilla, legalización y traducción oficial$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre","texto":"En un titular de registros sanitarios que opera en Colombia, el INVIMA requiere información adicional y el plazo empieza a correr. Lo que está en juego es el criterio de certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre con tus propias palabras y reconocer por qué importa en curso de Gestión Documental de Trámites ante el INVIMA.","Relacionar certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre con unidad 3. Documentos legales, apostilla, legalización y traducción oficial y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Compara el CPP del esquema OMS y el CVL, quién los emite y cómo se usan en la renovación de registros con vigencia temporal (p. ej. fitoterapéuticos) y en modificaciones (Decreto 334 de 2022, art. 3)."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre aparece en medio de una decisión que no admite improvisación: el INVIMA requiere información adicional y el plazo empieza a correr. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Documentos legales, apostilla, legalización y traducción oficial. El objetivo del curso es claro: Que el estudiante gestione de forma trazable, oportuna y sin rechazos la documentación de los trámites de medicamentos ante el INVIMA, desde la obtención y legalización de documentos hasta la radicación, el seguimiento, el archivo y el control de vencimientos del portafolio. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Compara el CPP del esquema OMS y el CVL, quién los emite y cómo se usan en la renovación de registros con vigencia temporal (p. ej. fitoterapéuticos) y en modificaciones (Decreto 334 de 2022, art. 3).","Una pregunta que se usa para comprobar esta clase es: «¿Qué es un Certificado de Producto Farmacéutico (CPP) tipo OMS?» La respuesta correcta se apoya en lo siguiente: El CPP del esquema de certificación de la OMS lo emite la autoridad sanitaria del país exportador e informa el estado de autorización del producto y el cumplimiento de BPM del fabricante. Se usa en trámites de productos importados. La fuente citada es: Esquema de certificación de la OMS.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Documentos legales, apostilla, legalización y traducción oficial y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasificar el producto. Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente. Evidencia que debe quedar: Clasificación sustentada.","Verificar el requisito vigente. Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado. Evidencia que debe quedar: Norma citada y vigente.","Preparar la evidencia. Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones. Evidencia que debe quedar: Expediente indexado.","Radicar y responder. Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables. Evidencia que debe quedar: Radicado y respuesta.","Mantener la autorización. Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas. Evidencia que debe quedar: Registro actualizado.","Vigilar el entorno. Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio. Evidencia que debe quedar: Informe de inteligencia regulatoria.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Un importador ficticio debe renovar un registro con documentos de un fabricante en un país parte de la Convención de La Haya y de otro que no lo es (datos simulados). Faltan cinco semanas para radicar y nadie ha iniciado el trámite de los documentos. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre»?","respuesta":"Compara el CPP del esquema OMS y el CVL, quién los emite y cómo se usan en la renovación de registros con vigencia temporal (p. ej. fitoterapéuticos) y en modificaciones (Decreto 334 de 2022, art. 3)."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Documentos legales, apostilla, legalización y traducción oficial.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Certificado de producto farmacéutico | AEMPS. AEMPS (España) (ES)","url":"https://www.aemps.gob.es/comercio-exterior/certificado-de-producto-farmaceutico"},{"cita":"[Página web] Proyecto de la Red PARF en CPF / PANDRH's CPP Project. OPS/PRAIS (ES)","url":"https://prais.paho.org/?p=17458"},{"cita":"[Página web] Decreto 334 de 2022 - renovación, modificación y suspensión de registros sanitarios (con modificaciones Dec. 322 y 1474 de 2023). Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/compilacion/docs/decreto_0334_2022.htm"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre"}],"keywords":["curso","gestión","documental","trámites","invima","certificado","producto","farmacéutico","venta","libre","unidad","documentos"],"mapa":{"centro":"Certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Unidad 3. Documentos legales, apostilla, legalización y traducción oficial","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Clasificar el producto","Verificar el requisito vigente","Preparar la evidencia"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Clasificación sustentada","Norma citada y vigente","Expediente indexado"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se construye y se sostiene un trámite regulatorio","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Clasificar el producto","detalle":"Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente.","icono":"Search","evidencia":"Clasificación sustentada"},{"titulo":"Verificar el requisito vigente","detalle":"Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado.","icono":"ClipboardList","evidencia":"Norma citada y vigente"},{"titulo":"Preparar la evidencia","detalle":"Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones.","icono":"Workflow","evidencia":"Expediente indexado"},{"titulo":"Radicar y responder","detalle":"Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables.","icono":"FileCheck","evidencia":"Radicado y respuesta"},{"titulo":"Mantener la autorización","detalle":"Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas.","icono":"RefreshCw","evidencia":"Registro actualizado"},{"titulo":"Vigilar el entorno","detalle":"Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio.","icono":"CheckCircle2","evidencia":"Informe de inteligencia regulatoria"}]},"caso":{"titulo":"Certificado de Producto Farmacéutico (CPP) tipo OMS y Certificado de Venta Libre","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 3. Documentos legales, apostilla, legalización y traducción oficial: una situación que exige documentar la decisión. La pregunta que decide esta clase es: ¿Qué es un Certificado de Producto Farmacéutico (CPP) tipo OMS?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Un certificado de la autoridad del país exportador sobre el producto y su fabricante.","correcta":true,"retro":"Correcto. Sigue el esquema de certificación de la OMS."},{"texto":"Una factura comercial del fabricante que acredita la compra del producto.","correcta":false,"retro":"No es un documento comercial."},{"texto":"Un certificado que emite el Invima a los productos fabricados en Colombia para venderlos aquí.","correcta":false,"retro":"Lo emite la autoridad del país exportador."},{"texto":"Un documento interno del importador con la lista de precios del producto.","correcta":false,"retro":"No es un documento interno."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
