  -- 27. Caso: organizar el expediente y el tablero de control de un portafolio de 25 registros
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: organizar el expediente y el tablero de control de un portafolio de 25 registros$t$
     AND m.title = $u$Unidad 4. Organización del expediente regulatorio, archivo y control de vencimientos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: organizar el expediente y el tablero de control de un portafolio de 25 registros$t$, $u$Unidad 4. Organización del expediente regulatorio, archivo y control de vencimientos$u$;
